import {representedState,validateRelease} from './state.js';
import {Panorama} from './viewer.js';
import {PhoneMotion} from './motion.js';
import {Ambient} from './ambient.js';
const $=id=>document.getElementById(id);let config,viewer,motion,current,entered=false,loading=false;const ambient=new Ambient();
const getJSON=async url=>{const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`Cannot load ${url}`);return r.json();};
function position(el,yaw,pitch){const p=viewer?.project(yaw,pitch);el.hidden=!p;if(p){el.style.left=`${p.x}px`;el.style.top=`${p.y}px`;}}
function place(){if(!entered||!viewer)return;position($('north'),0,.015);position($('plate'),.16,-1.15);}
async function loadState(index){if(loading)return;loading=true;$('loading').hidden=false;try{const url=config.states[index].asset;if(viewer)await viewer.load(url);else {$('fallback').src=url;await $('fallback').decode();}current=index;ambient.setPhase(index);$('failure').hidden=true;$('cycle').hidden=index!==6;if(!viewer){$('north').hidden=false;$('north').style.cssText='left:50%;top:50%;';$('plate').hidden=false;$('plate').style.cssText='left:50%;top:75%;';}else place();}finally{loading=false;$('loading').hidden=true;}}
function fields(){const state=representedState(config);const entries=[['RELEASE',`${config.version} · ${config.status}`],['CREATED',config.createdAt],['SEALED',config.sealedAt||'UNSEALED'],['STATE AUTHORITY','Predetermined temporal state machine'],['DEPARTURE EVENT',config.departureEvent?`${config.departureEvent.eventId} · ${config.departureEvent.basis} · ${config.departureEvent.occurredAt}`:'UNRECORDED'],['RETURN EVENT','UNRECORDED'],['CURRENT REPRESENTED STATE',`${config.states[current].id} · ${config.states[current].name}`],['CLOCK BASIS',`${state.clockStatus} · ${config.clockSource}`],['SOURCE COMMIT','See external release receipt; manifest does not embed its own containing commit'],['REALITY STATUS',config.realityStatus]];$('seal-fields').replaceChildren(...entries.flatMap(([label,value])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;return[dt,dd];}));}
async function start(){try{config=validateRelease(await getJSON('release.json'));try{viewer=new Panorama($('panorama'),place);motion=new PhoneMotion(viewer,$('motion'),$('motion-status'),$('recenter'));}catch{$('motion').hidden=true;$('panorama').hidden=true;$('fallback').hidden=false;}const r=representedState(config);await loadState(r.index);}catch(e){$('failure').textContent='This place could not open. Please reload.';$('failure').hidden=false;$('enter').disabled=true;console.error(e);}}
$('enter').addEventListener('click',async()=>{if(loading||!config)return;entered=true;document.body.classList.add('entered');$('experience').hidden=false;setTimeout(()=>{$('intro').hidden=true;},850);$('panorama').focus();place();});
$('sound').addEventListener('click',async()=>{try{const on=await ambient.toggle();$('sound').setAttribute('aria-pressed',String(on));$('sound').setAttribute('aria-label',on?'Turn sound off':'Turn sound on');$('sound').textContent=on?'≋':'◌';}catch{$('sound').disabled=true;}});
$('full').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('full').hidden=true;}});
document.addEventListener('fullscreenchange',()=>$('full').setAttribute('aria-label',document.fullscreenElement?'Exit full screen':'Enter full screen'));
for(const button of document.querySelectorAll('[data-close]'))button.addEventListener('click',()=>button.closest('dialog').close());
$('seal').addEventListener('click',()=>{fields();$('seal-dialog').showModal();});
$('north').addEventListener('click',()=>{if(config.north.status==='READY'){const dest=config.north.destination;if(dest==='north/north.mp4'){$('north-video').src=dest;$('north-video').hidden=false;$('north-message').hidden=true;$('north-dialog').showModal();}else window.location.assign(dest);}else $('north-dialog').showModal();});
$('north-dialog').addEventListener('close',()=>$('north-video').pause());
$('plate').addEventListener('click',()=>{viewer&&(viewer.pitch=-1.15,viewer.yaw=.16,viewer.onManualMove?.(),viewer.draw());});
$('verify').addEventListener('click',async()=>{$('verify').disabled=true;$('verification').textContent='Checking…';try{if(!crypto.subtle)throw new Error('Secure browser verification unavailable');const m=await getJSON('manifest.json');if(!Array.isArray(m.files)||m.files.length>100)throw new Error('Invalid manifest');let count=0;for(const f of m.files){if(!/^[a-zA-Z0-9_./-]+$/.test(f.path)||f.path.includes('..')||f.path.startsWith('/')||!/^[0-9a-f]{64}$/.test(f.sha256))throw new Error('Invalid manifest entry');const r=await fetch(f.path,{cache:'no-store'});if(!r.ok)throw new Error(`Missing ${f.path}`);const bytes=await r.arrayBuffer();const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');if(digest!==f.sha256||bytes.byteLength!==f.bytes)throw new Error(`Mismatch: ${f.path}`);count++;}$('verification').textContent=`${count} files match this manifest. Independent timestamp evidence remains separate.`;}catch(e){$('verification').textContent=`Verification incomplete: ${e.message}`;}finally{$('verify').disabled=false;}});
async function tick(){if(!config||loading)return;const state=representedState(config);if(state.index!==current){if(state.index===6&&entered&&!matchMedia('(prefers-reduced-motion:reduce)').matches){document.body.classList.add('dawn-transition');await new Promise(r=>setTimeout(r,1000));}try{await loadState(state.index);}catch{$('failure').textContent='The next scene could not load. The previous scene remains visible; retrying shortly.';$('failure').hidden=false;}document.body.classList.remove('dawn-transition');}}
setInterval(tick,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});window.addEventListener('panorama-lost',()=>{motion?.destroy();viewer=null;$('panorama').hidden=true;$('fallback').hidden=false;loadState(current);});
start();
